package org.sleepwell.app;
import android.content.Context;import android.os.*;import java.util.concurrent.*;import java.lang.ref.WeakReference;
/** Retained bounded worker; configuration never sends commands to the hub. */
final class PirSettingsJob {
 interface Observer{void changed();}final Context app;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());private WeakReference<Observer> observer=new WeakReference<>(null);PirConfig draft;String message="";PirHttp.Reading reading;boolean busy=true;private String verified="";private volatile boolean closed;private volatile PirHttp request;private int generation;private boolean checking;
 PirSettingsJob(Context context){app=context.getApplicationContext();worker.execute(()->{PirConfig config;String issue="";try{config=PirSettings.load(app);}catch(Exception failure){long revision;try{revision=PirSettings.prefs(app).getLong("revision",0);}catch(Exception ignored){revision=0;}config=PirConfig.empty(revision);issue="Saved PIR connection unavailable. Enter it again or disconnect.";}PirConfig value=config;String error=issue;main.post(()->{if(closed)return;draft=value;busy=false;message=error;publish();});});}
 void observe(Observer value){observer=new WeakReference<>(value);value.changed();}void detach(Observer value){if(observer.get()==value)observer.clear();}private void publish(){Observer target=observer.get();if(!closed&&target!=null)target.changed();}private static String identity(PirConfig config){return config.endpoint+"\n"+config.token+"\n"+config.entity;}
 void check(PirConfig input){if(busy||closed)return;input.validate();draft=input;busy=true;checking=true;reading=null;message="Reading the configured hub entity…";publish();int ticket=++generation;PirHttp http=new PirHttp();request=http;worker.execute(()->{PirHttp.Reading result=null;String issue="";try{result=http.read(input,()->!closed&&generation==ticket);}catch(Exception failure){issue="PIR could not be read. Check the server, token, entity and trusted HTTPS certificate.";}PirHttp.Reading value=result;String error=issue;main.post(()->{if(closed||ticket!=generation)return;request=null;checking=false;busy=false;reading=value;if(value!=null&&value.quality.equals("HUB_STATE")){draft=new PirConfig(input.endpoint,input.token,input.entity,value.deviceClass,input.enabled,input.revision);verified=identity(draft);message=value.state==1?"Hub currently reports motion/occupied.":"Hub currently reports clear.";}else message=value==null?error:value.quality.equals("UNSUPPORTED")?"Choose an entity whose device_class is motion or occupancy.":"The hub state is unknown or unavailable. It cannot qualify this connection.";publish();});});}
 void save(PirConfig input){if(busy||closed)return;input.validate();if(input.enabled&&!verified.equals(identity(input))){message="Read this entity successfully before enabling and saving it.";draft=input;publish();return;}draft=input;busy=true;message="Saving for the next manually started night…";publish();worker.execute(()->{PirConfig result=null;String issue="";try{result=PirSettings.save(app,input);}catch(Exception failure){issue=failure instanceof IllegalStateException?failure.getMessage():"PIR connection could not be saved.";}PirConfig value=result;String error=issue;main.post(()->{if(closed)return;busy=false;if(value!=null){draft=value;message=value.enabled?"Saved for the next manually started night. Current recordings keep their frozen connection.":"Saved. External PIR is off.";}else message=error;publish();});});}
 void disconnect(){if(busy||draft==null||closed)return;long revision=draft.revision;busy=true;publish();worker.execute(()->{String issue="";try{PirSettings.disconnect(app,revision);}catch(Exception failure){issue="PIR could not be disconnected. Reopen and retry.";}String error=issue;main.post(()->{if(closed)return;busy=false;if(error.isEmpty()){draft=PirConfig.empty(revision+1);verified="";reading=null;message="Disconnected. Current recordings keep their frozen connection until they stop.";}else message=error;publish();});});}
 void cancelTest(){if(!checking)return;generation++;checking=false;busy=false;PirHttp http=request;request=null;if(http!=null)http.cancel();message="PIR read cancelled.";publish();}
 void close(){if(closed)return;cancelTest();closed=true;observer.clear();worker.shutdown();}
}
